  ?riskScore2015 gemr:hasCountry ?countryNode ;
                 gemr:hasYear ?year2015 ;
                 gemr:governanceScore ?governance2015 .
  ?year2015 gemr:yearValue "2015" .

  ?riskScore2020 gemr:hasCountry ?countryNode ;
                 gemr:hasYear ?year2020 ;
                 gemr:governanceScore ?governance2020 .
  ?year2020 gemr:yearValue "2020" .

  ?countryNode gemr:countryName ?country .
  FILTER(?country IN ("Brazil", "China", "Mexico", "Philippines", "Poland", "Thailand"))

  ?obs2015 gemr:hasCountry ?countryNode ;
           gemr:hasYear ?year2015 ;
           rdf:type gemr:Observation ;
           gemr:observationType "PrivateDefaultRate" ;
           gemr:observationValue ?defaultRate2015 .

  ?obs2020 gemr:hasCountry ?countryNode ;
           gemr:hasYear ?year2020 ;
           rdf:type gemr:Observation ;
           gemr:observationType "PrivateDefaultRate" ;
           gemr:observationValue ?defaultRate2020 .

  FILTER(?governance2020 > ?governance2015)
  FILTER(?defaultRate2020 < ?defaultRate2015)
}
