WHERE {
  {
    SELECT ?country ?maxDefaultRate
    WHERE {
      ?obs rdf:type gemr:Observation ;
           gemr:observationValue ?defaultRate ;
           gemr:hasCountry ?country ;
           gemr:hasYear ?year .
      ?country gemr:countryName ?countryName .
      ?year gemr:yearValue ?yearValue .
      FILTER EXISTS {
        ?obs rdf:type gemr:PrivateDefaultRateObservation .
      }
    }
    GROUP BY ?country
    HAVING(MAX(?defaultRate) AS ?maxDefaultRate)
  }
  ?obs rdf:type gemr:Observation ;
       gemr:observationValue ?maxDefaultRate ;
       gemr:hasCountry ?country ;
       gemr:hasYear ?year .
  ?year gemr:yearValue ?yearValue .
  ?country gemr:countryName ?countryName .
}

