                 gemr:hasYear ?year2020 ;
                 gemr:governanceScore ?governanceScore2020 .
  ?year2020 gemr:yearValue "2020"^^xsd:string .

  FILTER(?governanceScore2020 > ?governanceScore2015)

  ?defaultRate2015 rdf:type gemr:Observation ;
                   gemr:hasCountry ?country ;
                   gemr:hasYear ?year2015 ;
                   gemr:observationValue ?defaultRate2015 .

  ?defaultRate2020 rdf:type gemr:Observation ;
                   gemr:hasCountry ?country ;
                   gemr:hasYear ?year2020 ;
                   gemr:observationValue ?defaultRate2020 .

  FILTER(?defaultRate2020 < ?defaultRate2015)

